import {mountWhyAsteroid} from './pages/home.js';
import {miningDashboardPage,miningMount,miningUnmount} from './pages/apps/mining-dashboard.js';
// English is the only supported website language.
const siteLanguage = 'en';
import {mountAsteroid} from './pages/home.js';
import {navigation} from './pages/shared/navigation.js';
import {network,products,exchanges,partners,team,roadmap} from './pages/shared/network.js';
import {pages} from './pages/shared/pages.js';
// Styles are bundled from src/styles/site.css by scripts/build.mjs.
const app=document.querySelector('#app');
let theme;try{theme=localStorage.getItem('numen-theme')||'light'}catch{theme='light'}
let menuOpen=false,filter='All';
// English is the source language; optional machine translation happens in-place.
const dictionary={en:{search:'Search',theme:'Toggle theme',menu:'Toggle navigation',skip:'Skip to main content',explore:'Explore',noInfo:'Information only',home:'Home'}};
const t=(key)=>dictionary.en[key]||key;
const navTitle=(s)=>s;

let disposeAsteroid=()=>{};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" ${/^https?:/.test(url)?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)} <span aria-hidden="true">↗</span></a>`;
const link=(label,url)=>`<a href="${esc(url)}" data-link>${esc(label)}</a>`;
// Homepage CTA: escape plain text, then add the arrow as real HTML.
// Never pass HTML markup inside a label to href() or link(): those helpers escape labels.
const homeCTA = (label, url, primary = false) => {
  const external = /^https?:\/\//i.test(url);
  const attrs = external ? 'target="_blank" rel="noopener noreferrer"' : 'data-link';
  const style = primary ? 'btn-primary' : 'btn-secondary';
  return `<a class="btn ${style} cta-kaspa" href="${esc(url)}" ${attrs}>` +
    `<span class="cta-label">${esc(label)}</span>` +
    `<span class="cta-arrow" aria-hidden="true">›</span></a>`;
};
const card=(title,desc,url,tag,icon='↗')=>`<article class="feature-card"><div class="feature-top"><span class="card-icon">${icon}</span>${tag?`<span class="eyebrow">${esc(tag)}</span>`:''}</div><h3>${esc(title)}</h3><p>${esc(desc)}</p>${url?(/^https?:/.test(url)?href(url,'Explore','card-link'):link('Explore →',url)):'<span class="muted tiny">Information only</span>'}</article>`;
// PoScan visualization: edit the heading and controls here.
// The illustration shows model registration separately from deterministic-asteroid consensus mining.
function asteroid(){return `<section class="proof-experience proof-compact proof-minimal" id="poscan-visual" aria-label="Numen object identity concept animation">
<h2 class="proof-minimal-title">Numen Blockchain</h2>
<div class="proof-screen"><canvas class="asteroid-canvas" role="img" aria-label="Three connected steps: object scanning and 3D model, PoScan mining and geometry vectors, then object record and blockchain. Concept illustration."></canvas></div>
<div class="proof-step-labels"><span>One object.</span><span>One digital fingerprint.</span><span>One blockchain.</span></div>
</section>`}
// Self-contained developer examples. Never include a funded private key in public code.
const devCode=(label,code)=>`<div class="developer-example"><div class="developer-example-heading"><strong>${esc(label)}</strong><button type="button" class="copy-btn" data-copy="${esc(code)}">Copy</button></div><pre><code>${esc(code)}</code></pre></div>`;
function developerReference(path){
 if(path==='/developers/evm')return `<section class="developer-docs" aria-label="Solidity and EVM deployment guide"><div class="section-head"><span class="eyebrow">QUICK START</span><h2>Deploy your first Solidity contract</h2><p>These are example commands and source files. They do not deploy automatically or require you to share a private key with this website.</p></div>
 <div class="developer-doc-grid"><article><h3>1 · Configure Numen mainnet</h3><p>Add the network to an EVM wallet and fund the deployment address with enough NUMN to pay gas.</p>${devCode('Network settings',`Network: Numen Mainnet\nRPC: https://rpc.numen-network.org\nChain ID: 32026\nCurrency: NUMN\nDecimals: 18\nExplorer: https://explorer.numen-network.org`)}</article>
 <article><h3>2 · Write a simple contract</h3><p>This example stores a message and emits an event when it changes. It does not manage user funds.</p>${devCode('MessageBoard.sol',`// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\ncontract MessageBoard {\n    string public message;\n    event MessageUpdated(address indexed author, string value);\n\n    constructor(string memory initialMessage) {\n        message = initialMessage;\n    }\n\n    function setMessage(string calldata value) external {\n        message = value;\n        emit MessageUpdated(msg.sender, value);\n    }\n}`)}</article>
 <article><h3>3 · Compile and test</h3><p>Start with a local Hardhat project. Check compiler compatibility and choose a supported EVM target before broadcasting a mainnet transaction.</p>${devCode('Hardhat setup',`mkdir numen-contracts && cd numen-contracts\nnpm init -y\nnpm install --save-dev hardhat\nnpx hardhat --init`)}</article>
 <article><h3>4 · Read the chain using ethers.js</h3><p>Read-only RPC calls do not require a private key. Verify that the connected chain ID matches 32026.</p>${devCode('Read a block',`import { JsonRpcProvider } from "ethers";\n\nconst provider = new JsonRpcProvider(\n  "https://rpc.numen-network.org"\n);\nconst chain = await provider.getNetwork();\nif (chain.chainId !== 32026n) {\n  throw new Error("Unexpected chain ID");\n}\nconsole.log(await provider.getBlockNumber());`)}</article></div>
 <div class="developer-note"><strong>Before deploying:</strong> Confirm the compiler's EVM target against the node runtime, test transaction and gas behavior, protect signing keys and review smart-contract security. Numen's native NUMN precompile is not an ordinary deployed ERC-20 token.</div>
 <div class="cta-row">${link('Network configuration →','/developers/network')}${link('Fungible token guide →','/developers/fungible-assets')}${href('https://docs.soliditylang.org/','Solidity documentation','btn btn-secondary')}</div></section>`;
 if(path==='/developers/fungible-assets')return `<section class="developer-docs"><div class="section-head"><span class="eyebrow">ERC-20</span><h2>Create fungible tokens</h2><p>Use an established, audited library for token accounting rather than implementing balances and allowances from scratch.</p></div>${devCode('Example ERC-20 with OpenZeppelin',`// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\nimport {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";\n\ncontract ExampleToken is ERC20 {\n    constructor(uint256 initialSupply) ERC20("Example Token", "EXT") {\n        _mint(msg.sender, initialSupply * 10 ** decimals());\n    }\n}`)}<p>Install <code>@openzeppelin/contracts</code> and test supply limits, permissions, transfers and approvals. This contract creates a separate ERC-20 token; it does not mint native NUMN.</p><div class="cta-row">${link('Solidity deployment guide →','/developers/evm')}${link('Network settings →','/developers/network')}</div></section>`;
 if(path==='/developers/non-fungible-assets')return `<section class="developer-docs"><div class="section-head"><span class="eyebrow">ERC-721 / ERC-1155</span><h2>Represent unique assets</h2><p>ERC-721 can represent individual digital records; ERC-1155 can manage mixed token collections. A token record does not independently prove physical authenticity or legal title.</p></div>${devCode('Minimal ERC-721 example',`// SPDX-License-Identifier: MIT\npragma solidity ^0.8.20;\n\nimport {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";\n\ncontract AssetRecord is ERC721URIStorage {\n    uint256 public nextId;\n    function mint(string calldata metadataURI) external {\n        uint256 tokenId = ++nextId;\n        _safeMint(msg.sender, tokenId);\n        _setTokenURI(tokenId, metadataURI);\n    }\n}`)}<p>This intentionally simplified example lets any caller mint their own record. Production asset issuance needs issuer authorization, metadata integrity, revocation or correction policies, and independent evidence linking a physical object to its record.</p><div class="cta-row">${link('Solidity deployment guide →','/developers/evm')}${link('RWA & tokenization →','/ecosystem/rwa')}</div></section>`;
 if(path==='/developers/guides')return `<section class="developer-docs"><div class="section-head"><span class="eyebrow">CONNECT</span><h2>Practical network requests</h2><p>Start with read-only requests and confirm the chain ID before any signing operation.</p></div>${devCode('JSON-RPC chain ID',`curl -X POST https://rpc.numen-network.org \\\n  -H "Content-Type: application/json" \\\n  -d '{"jsonrpc":"2.0","method":"eth_chainId","params":[],"id":1}'`)}<p>Expected hexadecimal chain ID: <code>0x7d1a</code> (32026 decimal). If the result differs, stop and verify the RPC endpoint.</p><div class="cta-row">${link('Smart contracts →','/developers/evm')}${link('RPC settings →','/developers/network')}</div></section>`;
 return '';
}
function header(){return `<a class="skip-link" href="#main-content">${t('skip')}</a><header class="site-header"><div class="container header-inner"><a href="/" data-link class="brand"><img src="/assets/numen-logo.png" alt="Numen logo"/><strong>NUMEN</strong><span>NETWORK</span></a><nav class="desktop-nav" aria-label="Main navigation"><a class="nav-button nav-direct-link" href="/" data-link>Home</a>${navigation.map(g=>(g.title==='Markets')?`<a class="nav-button nav-direct-link" href="${'/markets'}" data-link>${g.title}</a>`:`<div class="nav-group"><button type="button" class="nav-button" aria-haspopup="true" aria-expanded="false">${navTitle(g.title)}<span class="nav-chevron" aria-hidden="true"></span></button><div class="mega"><div class="mega-title">${g.icon} ${navTitle(g.title)}</div><div class="mega-links">${g.links.map(([t,u])=>link(t,u)).join('')}</div></div></div>`).join('')}</nav><div class="header-actions"><button id="theme-btn" class="icon-btn" aria-label="${t('theme')}">${theme==='dark'?'☼':'☾'}</button><button id="menu-btn" class="icon-btn mobile-only" aria-label="${t('menu')}" aria-expanded="${menuOpen}" aria-controls="mobile-navigation">${menuOpen?'✕':'☰'}</button></div></div>${menuOpen?`<div id="mobile-navigation" class="mobile-menu container" aria-label="Mobile navigation"><a class="mobile-resource-link" href="/" data-link>Home</a>${navigation.map(g=>(g.title==='Markets')?`<a class="mobile-resource-link" href="${'/markets'}" data-link>${g.title}</a>`:`<details><summary>${navTitle(g.title)}</summary>${g.links.map(([t,u])=>link(t,u)).join('')}</details>`).join('')}</div>`:''}</header>`}
const footerIconPaths={'github':`<path d="M9 19c-4 1-4-2-6-2m12 4v-3.9a3.4 3.4 0 0 0-.9-2.6c3-.3 6.1-1.5 6.1-6.8a5.3 5.3 0 0 0-1.5-3.7 4.9 4.9 0 0 0-.1-3.7S17.4 0 15 2a13 13 0 0 0-7 0C5.6 0 4.4.3 4.4.3a4.9 4.9 0 0 0-.1 3.7 5.3 5.3 0 0 0-1.5 3.7c0 5.3 3.1 6.5 6.1 6.8A3.4 3.4 0 0 0 8 17.1V21"/>`,'telegram':`<path d="m22 2-7.4 20-4.5-7-7-4.4L22 2ZM10.1 15l5.4-5.3"/>`,'x':`<path d="M4 3h4l12 18h-4L4 3Zm16 0L4 21"/>`,'discord':`<path d="M7 6a17 17 0 0 1 10 0l1.5 2c2 1 3 6 3 9a17 17 0 0 1-5 3l-1-2M7 6 5.5 8C3.5 9 2.5 14 2.5 17a17 17 0 0 0 5 3l1-2M8 18a17 17 0 0 0 8 0M9 13h.01M15 13h.01"/>`,'youtube':`<rect x="2" y="5" width="20" height="14" rx="4"/><path d="m10 9 5 3-5 3V9Z"/>`,'medium':`<circle cx="5" cy="12" r="4"/><ellipse cx="14" cy="12" rx="3" ry="6"/><ellipse cx="21" cy="12" rx="1" ry="5"/>`,'linkedin':`<rect x="3" y="9" width="4" height="12"/><circle cx="5" cy="5" r="2"/><path d="M11 21V9h4v2a4 4 0 0 1 7 3v7h-4v-7a2 2 0 0 0-4 0v7"/>`,'instagram':`<rect x="2" y="2" width="20" height="20" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="18" cy="6" r="1"/>`,'tiktok':`<path d="M14 3v12a5 5 0 1 1-5-5m5-7c1 4 3 6 7 6"/>`,'bitcointalk':`<path d="M5 8h14v9H9l-4 4v-4H3V8h2Zm4-4h12v10"/>`,'reddit':`<circle cx="12" cy="12" r="9"/><circle cx="8.5" cy="13" r="1"/><circle cx="15.5" cy="13" r="1"/><path d="M8 16c2.5 2 5.5 2 8 0M12 4l1-2 4 1"/>`,'email':`<rect x="2" y="5" width="20" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>`};
function footerIcon(name){return `<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${footerIconPaths[name]||''}</svg>`}
function footer(){const socials=[['github','GitHub',network.github],['discord','Discord',network.discord],['telegram','Telegram',network.telegram],['x','X',network.x],['reddit','Reddit',network.reddit],['bitcointalk','BitcoinTalk',network.bitcointalk],['email','Contact',`mailto:${network.email}`]];return `<footer class="footer footer-original-layout"><div class="container"><div class="footer-columns">${navigation.map(g=>`<div class="footer-column"><h4>${navTitle(g.title)}</h4>${g.links.slice(0,6).map(([t,u])=>link(t,u)).join('')}</div>`).join('')}</div><div class="footer-head"><div><div class="brand footer-brand"><img src="/assets/numen-logo.png" alt=""/><strong>NUMEN</strong></div><p>Proof of Scan. Open-source Layer 1 infrastructure.</p></div><div class="footer-social" aria-label="Official Numen channels">${socials.map(([icon,label,url])=>`<a href="${esc(url)}" ${icon==='email'?'':'target="_blank" rel="noopener noreferrer"'} title="${label}" aria-label="${label}">${footerIcon(icon)}<span class="sr-only">${label}</span></a>`).join('')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Numen Network · Open-source community</span><span>Technical content based on Whitepaper v1.1 · September 2026</span></div></div></footer>`}
function appsOverview(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS</span><h1>Explore the Numen ecosystem.</h1><p>Discover practical tools for self-custody, blockchain transparency, geometric mining and programmable asset markets. Explore what works today and what the ecosystem can build next.</p></section><section class="section container"><div class="feature-grid">${card('NumenDEX','Token swaps and liquidity pools today; a foundation for future NFT marketplaces and tokenized 3D-linked asset trading.','/apps/numendex','DEFI & LIQUIDITY','⇄')}${card('Numen Explorer','Investigate blocks, mined 3D objects, transactions, EVM logs, ERC-20 tokens, accounts, governance and mining statistics.','/apps/explorer','ON-CHAIN TRANSPARENCY','↗')}${card('Numen Wallet','Self-custody accounts, transfers, governance, multisig, proxy accounts, vesting, validators and MetaMask interoperability.','/apps/wallet','SELF-CUSTODY','◈')}${card('Mining','Open-source blockchain node and CPU/GPU PoScan miner.','/apps/miner','PROOF OF SCAN','⚒')}${card('Validator','Validator onboarding is not yet publicly open.','/apps/validator','COMING SOON','⬡')}${card('3D Object Registry','Explore the potential of linking geometric models to programmable digital assets.','/apps/3d-object-registry','DEVELOPING','◇')}</div></section></main>`}
function appsWallet(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS / WALLETS</span><h1>Your assets. Your keys. Your Numen.</h1><p>Numen Wallet is more than a balance viewer: the open-source browser wallet combines account management, governance and advanced on-chain operations in one self-custody interface.</p><div class="cta-row">${href(network.wallet,'Open Numen Wallet','btn btn-primary')}</div></section><section class="section container"><div class="content-grid"><article class="content-block"><h2>Accounts and transfers</h2><p>Create and organize multiple accounts, monitor balances, send and receive NUMN. Locally managed keys are encrypted in the browser and signatures require password authorization.</p></article><article class="content-block"><h2>On-chain governance</h2><p>Review referenda, participate in delegation, and follow treasury spends and bounties from the wallet interface.</p></article><article class="content-block"><h2>Advanced account controls</h2><p>Work with multisignature transactions, proxy permissions, vesting schedules and on-chain identity with registrar verification.</p></article><article class="content-block"><h2>Validators and session keys</h2><p>Wallet source includes validator seats and session-key workflows. Public validator admission remains subject to network rules.</p></article><article class="content-block"><h2>EVM and MetaMask</h2><p>Add Numen to MetaMask, manage EVM-linked balances and sign ERC-20 transfers with MetaMask. The wallet does not take custody of MetaMask keys.</p></article><article class="content-block"><h2>Security and open source</h2><p>The wallet is a static application without a custody backend. Never enter your recovery phrase on an unverified site; inspect official source and security assumptions.</p></article></div><div class="feature-grid">${card('Numen Web Wallet','Open the official browser wallet.',network.wallet,'OPEN APP','◈')}${card('MetaMask Wallet','Connect MetaMask to Numen Mainnet. You will be asked to approve the network in MetaMask. Never share your recovery phrase or private key. Verify the RPC and chain ID before approval.','/apps/metamask','CONNECT','⬡').replace('href="/apps/metamask"','href="/apps/metamask" data-metamask-direct="true"')}${card('Wallet source code','Review the open-source implementation.',network.walletRepository,'GITHUB','⌘')}</div></section></main>`}
function appsMiner(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS / MINING</span><h1>Help secure Numen with geometric work.</h1><p>PoScan mining evaluates protocol-generated deterministic 3D objects. Run the open-source CPU/GPU miner or explore the blockchain node source.</p></section><section class="section container"><div class="feature-grid">${card('Blockchain Node','Explore the open-source Layer 1 node, runtime and network infrastructure.',network.nodeRepository,'GITHUB','⬡')}${card('PoScan Miner','Download the open-source CPU/GPU miner and review solo or pool setup.',network.miner,'DOWNLOAD','⚒')}${card('Mining Guide','Learn about rewards, mining requirements and operational considerations.','/participate/mining','GUIDE','↗')}</div></section></main>`}
function appsExplorer(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS / EXPLORER</span><h1>Every block tells a story.</h1><p>Numen Explorer turns blockchain activity into searchable, verifiable public information — from geometry-based block production to EVM execution and on-chain governance.</p><div class="cta-row">${href(network.explorer,'Open Numen Explorer','btn btn-primary')}${href(network.explorerRepository,'View source code','btn btn-secondary')}</div></section><section class="section container"><div class="content-grid"><article class="content-block"><h2>Blocks and 3D mining objects</h2><p>Inspect individual blocks and the 3D objects associated with PoScan mining. Trace the chain's geometric work rather than relying only on a transaction count.</p></article><article class="content-block"><h2>Transactions, extrinsics and events</h2><p>Search extrinsics, browse the nested call tree and inspect emitted events and transfers to understand what happened on-chain.</p></article><article class="content-block"><h2>Accounts and identities</h2><p>View account activity, on-chain identities, registrars and vesting schedules.</p></article><article class="content-block"><h2>EVM and ERC-20</h2><p>Explore EVM transactions, execution logs and ERC-20 token activity alongside the underlying Numen chain.</p></article><article class="content-block"><h2>Governance and treasury</h2><p>Follow OpenGov referenda and decision curves, treasury spends and bounties for transparent public oversight.</p></article><article class="content-block"><h2>Validators, miners and charts</h2><p>Review validator information, miner leaderboards and daily network aggregates in the analytics section.</p></article><article class="content-block"><h2>Global search</h2><p>Find blockchain records through a unified search experience across supported indexed entities.</p></article><article class="content-block"><h2>Built for developers</h2><p>The open-source stack indexes archive-node data using Subsquid and PostgreSQL, exposes GraphQL and renders a Next.js frontend. Indexed views depend on synchronization status.</p></article></div></section></main>`}
function appsDex(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS / DEFI</span><h1>NumenDEX: liquidity for a programmable 3D economy.</h1><p>NumenDEX is designed to connect assets, communities and capital on Numen. AMM-style token swaps and liquidity pools can provide a trading foundation for the network's expanding token ecosystem — and a pathway toward markets built around unique digital and 3D-linked assets.</p><div class="cta-row">${href(network.numendexRepository,'Explore NumenDEX source','btn btn-primary')}${link('Learn about tokenization →','/technology/tokenization')}</div></section><section class="section container"><div class="content-grid"><article class="content-block"><h2>Swap tokens without a traditional order book</h2><p>Automated market maker pools can enable token-for-token swaps using liquidity provided on-chain. Token availability, trading depth and execution quality depend on actual deployed pools.</p></article><article class="content-block"><h2>Make new tokens discoverable and tradable</h2><p>For builders launching tokens on Numen, decentralized liquidity can turn an issued asset into something users can exchange, price and integrate into applications.</p></article><article class="content-block"><h2>From 3D records to potential markets</h2><p>Imagine a registered 3D model linked to a digital collectible, a game item, an industrial twin or a tokenized asset. Smart contracts could allow those representations to be listed, exchanged or used in DeFi — provided compatible marketplace contracts and verified ownership arrangements are developed.</p></article><article class="content-block"><h2>NFTs and unique 3D assets: next-stage opportunity</h2><p>Fungible-token AMM pools do not automatically swap NFTs or unique 3D models. Dedicated NFT marketplace, fractionalization or other tokenization mechanisms would be needed to make these assets tradable. These are potential ecosystem extensions, not confirmed live NumenDEX features.</p></article><article class="content-block"><h2>Liquidity as an ecosystem catalyst</h2><p>Wallets, creators, developers and applications benefit from accessible exchange infrastructure. A healthy market can improve asset utility and developer opportunities, but does not guarantee liquidity, demand or returns.</p></article><article class="content-block"><h2>Built on Numen EVM</h2><p>Solidity-compatible smart contracts create a foundation for interoperable tokens and financial applications. Always verify official deployment addresses, audit status and pool liquidity before transacting.</p></article></div><div class="note"><strong>Product status:</strong> The descriptions above distinguish token-swap architecture from proposed NFT and 3D-asset trading possibilities. No NFT or 3D marketplace launch is implied.</div></section></main>`}
function appsMetaMask(){return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">APPLICATIONS / METAMASK</span><h1>Connect MetaMask to Numen.</h1><p>Connect your existing EVM wallet, then approve adding or switching to Numen Mainnet. MetaMask will request your permission; the website cannot bypass wallet confirmation.</p><div class="cta-row"><button class="btn btn-primary" type="button" id="numen-metamask-connect">Connect MetaMask &amp; Add Numen</button><a class="btn btn-secondary" href="https://metamask.io/download/" target="_blank" rel="noopener noreferrer">Install MetaMask ↗</a></div><p id="numen-metamask-status" role="status" aria-live="polite"></p></section><section class="section container"><div class="content-grid"><article class="content-block"><h2>Network details</h2><p>Network: Numen Mainnet<br>RPC: https://rpc.numen-network.org<br>Chain ID: 32026 (0x7d1a)<br>Currency: NUMN<br>Explorer: https://explorer.numen-network.org</p></article><article class="content-block"><h2>Your approval is required</h2><p>The wallet extension opens its confirmation prompt for account access and network changes. Check the RPC and chain ID before approving. Never provide a seed phrase.</p></article></div></section></main>`}
function legacyPage(path){if(path==='/technology')return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">TECHNOLOGY</span><h1>Numen Technology</h1><p>Explore the geometry, blockchain infrastructure and programmable applications behind Numen.</p></section><section class="section container"><div class="feature-grid">${navigation.find(n=>n.title==='Technology').links.map(([t,u])=>card(t,'Explore this Numen technology topic.',u,'TECHNOLOGY','◇')).join('')}</div></section></main>`;if(path==='/apps')return appsOverview();if(path==='/apps/wallet')return appsWallet();if(path==='/apps/miner')return appsMiner();if(path==='/apps/explorer'||path==='/ecosystem/explorer')return appsExplorer();if(path==='/apps/numendex'||path==='/ecosystem/numendex')return appsDex();if(path==='/apps/metamask')return appsMetaMask();if(path==='/ecosystem/web-wallet')return appsWallet();if(path==='/use')return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">USE NUMEN</span><h1>Get started with Numen.</h1><p>Create a wallet, find NUMN and discover ways to use the network.</p></section><section class="section container"><div class="feature-grid">${card('Create Wallet','Set up your self-custody Numen wallet.',network.wallet,'WALLET','◈')}${card('Get NUMN','Review market trackers and available exchanges.','/markets','MARKETS','↗')}${card('Mining','Explore CPU/GPU PoScan mining.','/participate/mining','MINING','⚒')}${card('Validators','Understand validator participation and admission.','/participate/validators','VALIDATORS','⬡')}${card('3D Object Registry','Explore geometric model records and availability.','/use/3d-object-registry','3D RECORDS','◇')}${card('NumenDEX','Explore decentralized exchange development.','/ecosystem/numendex','DEFI','⇄')}${card('Explorer','Inspect blocks, transactions and accounts.',network.explorer,'EXPLORER','↗')}${card('Cross-Chain Bridge','Learn about cross-chain integration plans.','/ecosystem/bridge','BRIDGE','⇄')}${card('Apps on Numen','Discover network applications.','/use/apps','APPS','⬡')}</div></section></main>`;if(path==='/use/apps')return appsOverview();if(path==='/mining/dashboard')return miningDashboardPage();if(path==='/learn')return learnHub();if(learnChapters[path.slice(7)])return learnArticle(path);if(path==='/whitepaper')return whitepaper();if(path==='/markets')return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">MARKETS</span><h1>Explore NUMN markets.</h1><p>Independent market trackers and exchanges in one place.</p></section><section class="section container page-content">${markets(path)}</section></main>`;const p=pages[path];if(!p)return `<main id="main-content" class="container section"><h1>Page not found</h1><p>The requested page does not exist.</p>${link('Back to home →','/')}</main>`;return `<main id="main-content"><section class="page-hero container"><span class="eyebrow">${esc(p.eyebrow)}</span><h1>${esc(p.title)}</h1><p>${esc(p.lead)}</p>${p.cta?`<div class="cta-row">${href(p.cta[1],p.cta[0],'btn btn-primary')}</div>`:''}</section><section class="section container page-content">${p.stats?`<div class="stat-grid">${p.stats.map(([a,b])=>`<div class="stat"><strong>${esc(a)}</strong><span>${esc(b)}</span></div>`).join('')}</div>`:''}${p.sections&&!path.startsWith('/participate/')?`<div class="content-grid">${p.sections.filter(([a])=>!/^sources?(?: and distinction)?$/i.test(String(a).trim())).map(([a,b])=>`<article class="content-block"><h2>${esc(a)}</h2><p>${esc(b)}</p></article>`).join('')}</div>`:''}${path.startsWith('/participate/')?participateDetail(path):''}${path==='/ecosystem'?productGrid():''}${path==='/ecosystem/numn-token'?numnTokenPage():''}${path==='/ecosystem/use-cases'?useCasesPage():''}${path==='/developers'?`<div class="section-head"><span class="eyebrow">OPEN-SOURCE REPOSITORIES</span><h2>Developer tools & source code</h2><p>Explore core infrastructure, EVM development, asset standards, indexing and open-source tools.</p></div><div class="feature-grid">${[['Numen Node','Layer 1 node, runtime and network source.',network.nodeRepository,'CORE'],['CPU/GPU Miner','PoScan external mining implementation.',network.minerRepository,'MINING'],['Web Wallet','Wallet application source.',network.walletRepository,'WALLET'],['Block Explorer','Explorer application source.',network.explorerRepository,'EXPLORER'],['Identity Registrar','On-chain identity registrar tooling.',network.registrarRepository,'IDENTITY'],['spectral3d','Geometric feature extraction library.',network.spectral3d,'GEOMETRY'],['spectral3d Calibration','Spectral registration and verification measurement bench.',network.spectral3dCalibration,'GEOMETRY'],['spectral3d CLI','Geometric analysis and mesh repair CLI.',network.spectral3dCli,'GEOMETRY'],['Official Website','Website source and documentation.',network.websiteRepository,'WEBSITE']].map(([name,desc,url,tag])=>card(name,desc,url,tag,'⌘')).join('')}</div><div class="section-head" style="margin-top:3rem"><span class="eyebrow">GUIDES & REFERENCES</span><h2>Build on Numen</h2></div><div class="feature-grid">${navigation.find(n=>n.title==='Developers').links.slice(1).map(([t,u])=>card(t,'Technical documentation and developer resources.',u,'GUIDE','⌘')).join('')}${card('3D modeling','Learn about deterministic mesh generation and geometry in PoScan.','/learn/proof-of-scan','CONCEPT','◇')}${card('3D scanning','Understand spectral features and the chain-defined scan pipeline.','/learn/proof-of-scan','CONCEPT','◇')}</div>`:''}${path==='/community'?`<div class="feature-grid">${navigation.find(n=>n.title==='Community').links.slice(1).map(([t,u])=>card(t,'Explore the Numen community and its initiatives.',u,'COMMUNITY','◎')).join('')}</div>`:''}${path==='/learn/roadmap'?`<div class="timeline">${roadmap.map(r=>`<article class="timeline-item"><span class="eyebrow">${r.period}</span><h2>${r.title}</h2><ul class="milestone-list">${r.items.map(i=>`<li class="milestone ${i.state}"><span class="milestone-icon" aria-hidden="true">${i.state==='done'?'✓':i.state==='progress'?'◌':'→'}</span><span>${esc(i.text)}</span><span class="milestone-state">${i.state==='done'?'Completed':i.state==='progress'?'In development':'Planned'}</span></li>`).join('')}</ul></article>`).join('')}</div>`:''}${(path.startsWith('/markets/')||path==='/markets')?markets(path):''}${path==='/community/partners'?`<div class="note">No verified official partnership entries are supplied for this build. Technical integrations and ecosystem projects will be listed separately once verified.</div>`:''}${path==='/community/team'?teamDirectory():''}${path==='/resources/faq'?faqDirectory():''}${path==='/community/channels'?`<div class="section-head"><span class="eyebrow">OFFICIAL SOCIAL CHANNELS</span><h2>Find Numen across the web</h2><p>Use these channels for community updates, technical discussions and public resources. Never share wallet recovery phrases with anyone.</p></div><div class="feature-grid">${[['GitHub','Open-source development',network.github],['Discord','Technical discussions',network.discord],['Telegram','Community discussion',network.telegram],['X','Network announcements',network.x],['Reddit','Community forum',network.reddit],['BitcoinTalk','Mining and cryptocurrency forum',network.bitcointalk],['Contact','Email the Numen contributors',`mailto:${network.email}`]].map(([a,b,u])=>card(a,b,u,'CHANNEL','↗')).join('')}</div>`:''}${path==='/developers/guides'?`<div class="section-head"><span class="eyebrow">QUICK LINKS</span><h2>Start building</h2></div><div class="feature-grid">${[['Network configuration','/developers/network'],['EVM & smart contracts','/developers/evm'],['Fungible assets','/developers/fungible-assets'],['Non-fungible assets','/developers/non-fungible-assets'],['GraphQL & indexing','/developers/graphql'],['CPU/GPU miner','/developers/numen-miner'],['Mining guide','/participate/mining'],['Whitepaper','/whitepaper']].map(([t,u])=>card(t,'Open the corresponding technical reference.',u,'GUIDE','⌘')).join('')}</div>`:''}${path==='/developers/graphql'?`<div class="note"><strong>Endpoint status:</strong> No official public GraphQL endpoint is advertised. Use the documented Numen RPC interfaces or operate an independent indexer.</div><div class="feature-grid">${card('RPC & network','Verified connection details for Numen mainnet.','/developers/network','REFERENCE','⌘')}${card('Developer guides','Integration workflows and practical setup notes.','/developers/guides','GUIDES','▤')}</div>`:''}${developerReference(path)}${path==='/developers/network'?`<div class="network-table">${[['Network','Numen Mainnet'],['Symbol',network.symbol],['EVM chain ID',network.chainId],['RPC',network.rpc],['WebSocket',network.wss],['Decimals',network.decimals],['Native ERC-20 precompile',network.nativeErc20]].map(([a,b])=>`<div><span>${esc(a)}</span><code>${esc(b)}</code><button class="copy-btn" data-copy="${esc(b)}">Copy</button></div>`).join('')}</div>`:''}${path==='/resources/docs'?`<div class="feature-grid">${[['PoScan specification','/learn/proof-of-scan'],['Developer tools','/developers'],['Network configuration','/developers/network'],['Whitepaper','/whitepaper']].map(([a,b])=>card(a,'Read documentation and technical reference.',b,'DOCUMENTATION','▤')).join('')}</div>`:''}<div class="page-more"><h2>Continue exploring</h2><div class="mini-links">${navigation.find(g=>g.links.some(([,u])=>u===path))?.links.filter(([,u])=>u!==path).slice(0,5).map(([t,u])=>link(t+' →',u)).join('')||link('Use Numen →','/use')}</div></div></section></main>`}
let disposeWhyAsteroid = () => {};
function miningReadmePage(){return `<main id="main-content" class="mining-guide-page">
<section class="page-hero container"><span class="eyebrow">APPLICATIONS / MINING</span><h1>Start mining NUMN.</h1><p>Set up your wallet, download the Numen blockchain node and install the open-source PoScan miner. Choose solo mining or a compatible pool, then monitor your results.</p><div class="cta-row"><a class="btn btn-primary" href="#mining-setup">Get started ↓</a><a class="btn btn-secondary" href="https://github.com/numen-network/numen-miner#readme" target="_blank" rel="noopener noreferrer">Full technical README ↗</a></div></section>
<section class="section container" id="mining-economics"><div class="section-head"><span class="eyebrow">MINING ECONOMICS</span><h2>Earn NUMN by securing the network</h2><p>Numen allocates 40% of its maximum token supply to permissionless Proof of Scan mining. Block rewards are issued over time and decrease through scheduled halvings.</p></div><div class="mining-stats-grid"><div class="mining-stat"><strong>16 NUMN</strong><span>Initial reward per block</span></div><div class="mining-stat"><strong>10 seconds</strong><span>Target block interval</span></div><div class="mining-stat"><strong>400M NUMN</strong><span>Maximum mining allocation</span></div><div class="mining-stat"><strong>12.5M blocks</strong><span>Halving interval · approximately 4 years</span></div></div><div class="mining-emission-panel"><div><h3>Predictable issuance. Progressive scarcity.</h3><p>The initial 16 NUMN reward halves every 12.5 million blocks: 16 → 8 → 4 → 2 NUMN and onward. At a 10-second target interval, the initial theoretical emission is 8,640 blocks and 138,240 NUMN per day. Actual output depends on block production and network conditions.</p><p>Miners also receive 20% of standard transaction fees and all tips, under the network fee rules. Rewards are not guaranteed for any individual miner.</p><a href="/tokenomics" data-link class="mining-text-link">Explore tokenomics →</a></div><div class="mining-emission-steps" aria-label="Scheduled mining reward halvings"><div><b>16</b><small>Epoch 1</small></div><div><b>8</b><small>Epoch 2</small></div><div><b>4</b><small>Epoch 3</small></div><div><b>2</b><small>Epoch 4</small></div></div></div></section>
<section class="section container" id="mining-hardware"><div class="section-head"><span class="eyebrow">CPU & GPU MINING</span><h2>Choose your hardware</h2><p>Numen's open-source miner supports GPU mining and optional CPU mining. Check current device support and benchmark before choosing your setup.</p></div><div class="mining-hardware-grid"><article class="mining-hardware-card"><div class="mining-hardware-visual"><svg viewBox="0 0 360 190" role="img" aria-label="Technical illustration of a graphics card with two cooling fans"><rect x="58" y="28" width="245" height="134" rx="14" fill="#252b45" stroke="#7c69dd" stroke-width="3"/><rect x="80" y="48" width="200" height="94" rx="8" fill="#39405e"/><circle cx="133" cy="95" r="36" fill="#202840" stroke="#a99bea" stroke-width="3"/><circle cx="224" cy="95" r="36" fill="#202840" stroke="#a99bea" stroke-width="3"/><g stroke="#a99bea" stroke-width="8" stroke-linecap="round"><path d="M133 66v58M104 95h58M112 74l42 42M154 74l-42 42M224 66v58M195 95h58M203 74l42 42M245 74l-42 42"/></g><circle cx="133" cy="95" r="11" fill="#8b7ae6"/><circle cx="224" cy="95" r="11" fill="#8b7ae6"/><rect x="300" y="66" width="14" height="58" rx="3" fill="#55bcb8"/><path d="M94 163v11h167v-11" fill="#e2ae62"/></svg></div><div class="mining-hardware-body"><span class="eyebrow">GPU MINING</span><h3>Mine with compatible graphics cards</h3><p>The official miner supports NVIDIA and AMD GPUs subject to architecture, driver and runtime requirements. Discover supported devices, monitor temperatures and adjust workload settings for your hardware.</p><code>numen-miner devices</code></div></article><article class="mining-hardware-card"><div class="mining-hardware-visual"><svg viewBox="0 0 360 190" role="img" aria-label="Technical illustration of a CPU processor and circuit board"><rect x="104" y="25" width="152" height="140" rx="18" fill="#29304a" stroke="#7869d7" stroke-width="4"/><rect x="128" y="49" width="104" height="92" rx="10" fill="#454e76" stroke="#a99bea" stroke-width="2"/><path d="M146 74h68M146 94h68M146 114h68" stroke="#79d3cf" stroke-width="5" stroke-linecap="round"/><g stroke="#9b8ee4" stroke-width="5"><path d="M125 10v15M156 10v15M187 10v15M218 10v15M125 165v15M156 165v15M187 165v15M218 165v15M88 53h16M88 84h16M88 115h16M88 146h16M256 53h16M256 84h16M256 115h16M256 146h16"/></g></svg></div><div class="mining-hardware-body"><span class="eyebrow">CPU MINING</span><h3>Participate using your processor</h3><p>CPU mining is optional in the external miner. Enable it alongside compatible GPUs, or disable GPU use for a CPU-only setup. Benchmark speed and consider energy costs.</p><code>numen-miner --cpu --no-gpu --url ws://127.0.0.1:9944</code></div></article></div></section>
<section class="section container" id="mining-setup"><div class="section-head"><span class="eyebrow">QUICK START</span><h2>Everything you need to begin</h2><p>Follow these steps in order. The wallet and source repositories are maintained separately.</p></div>
<div class="mining-setup-grid">
<article class="mining-setup-card"><span class="mining-step-number">01 / WALLET</span><div class="mining-setup-icon" aria-hidden="true">◈</div><h3>Create your Numen wallet</h3><p>Generate a self-custody wallet and save your recovery phrase securely offline. Use your <strong>public address</strong> to receive mining rewards.</p><a class="btn btn-primary" href="https://wallet.numen-network.org/" target="_blank" rel="noopener noreferrer">Create wallet ↗</a></article>
<article class="mining-setup-card"><span class="mining-step-number">02 / NODE</span><div class="mining-setup-icon" aria-hidden="true">⬡</div><h3>Download the blockchain node</h3><p>Access the Numen Layer 1 node source code, installation instructions and available releases. Running your own node is required for the solo setup described below.</p><a class="btn btn-primary" href="https://github.com/numen-network/numen" target="_blank" rel="noopener noreferrer">Get blockchain node ↗</a></article>
<article class="mining-setup-card"><span class="mining-step-number">03 / MINER</span><div class="mining-setup-icon" aria-hidden="true">⚒</div><h3>Download the PoScan miner</h3><p>Get the open-source CPU/GPU mining software. Check the repository README and select the release suitable for your operating system and hardware.</p><a class="btn btn-primary" href="https://github.com/numen-network/numen-miner" target="_blank" rel="noopener noreferrer">Get miner ↗</a></article>
</div></section>
<section class="section container"><div class="section-head"><span class="eyebrow">MINING METHODS</span><h2>Solo mining or pool mining?</h2><p>Both methods contribute computational work to Numen. The best fit depends on your equipment and preference for payout frequency.</p></div><div class="mining-method-grid"><article><span class="eyebrow">SOLO</span><h3>Run your own node</h3><p>Connect your miner to a synchronized Numen node under your control. When your work finds an eligible block, its block reward is credited to your configured public address. Rewards can be infrequent and unpredictable.</p><strong>Requires your own node</strong></article><article><span class="eyebrow">POOL</span><h3>Join a mining pool</h3><p>Connect directly to a compatible pool using its published endpoint and your payout address. Pools aggregate participants' work and distribute rewards under their own payout and fee policies.</p><strong>No personal node required for typical pool setups</strong></article></div></section>
<section class="section container"><div class="section-head"><span class="eyebrow">CONFIGURATION</span><h2>Choose your mining setup</h2><p>Expand a section for practical guidance. Always follow the current repository documentation for version-specific flags.</p></div>
<div class="mining-guide-accordion">
<details open><summary>Solo mining with your own node</summary><div class="mining-accordion-body"><p>Run a synced Numen node with your public reward address and enable the mining RPC. Then point the external miner to the local node. Example commands from the miner README:</p><div class="mining-code"><span>Start the node</span><pre><code>./numen --chain mainnet-raw.json --miner &lt;YOUR_PUBLIC_ADDRESS&gt;</code></pre></div><div class="mining-code"><span>Connect the miner</span><pre><code>./numen-miner --url ws://127.0.0.1:9944</code></pre></div><p>Command syntax may vary by release. Protect mining RPC access and do not expose port 9944 publicly.</p></div></details>
<details><summary>Mining through a pool</summary><div class="mining-accordion-body"><p>Choose an independently operated Numen pool, verify its current connection instructions and payout rules, then configure the miner using the pool's published endpoint. A pool may reduce reward variance but introduces operator and payout risk.</p><a href="/participate/mining-pools" data-link>Explore mining pools →</a></div></details>
<details><summary>CPU, GPU and device setup</summary><div class="mining-accordion-body"><p>Hardware support and performance vary by release and device. Use the official miner README to inspect supported NVIDIA, AMD and CPU options, list devices and benchmark before continuous operation. Monitor temperatures and electricity costs.</p><a href="https://github.com/numen-network/numen-miner#readme" target="_blank" rel="noopener noreferrer">View hardware options and commands ↗</a></div></details>
<details><summary>Verify rewards and troubleshoot</summary><div class="mining-accordion-body"><p>Review accepted shares or solo block production in miner logs. Check your public reward address and any received payouts in the Numen Explorer. If mining does not start, check node synchronization, network connectivity, RPC access, device compatibility and the current README.</p><a href="https://explorer.numen-network.org/" target="_blank" rel="noopener noreferrer">Open Numen Explorer ↗</a></div></details>
</div></section>
<section class="section container"><div class="mining-guide-warning"><strong>Security and expectations.</strong> Never share your recovery phrase or private keys. Verify downloaded binaries and publishers, do not disable antivirus protection, and do not expose mining RPC ports to the public internet. PoScan uses protocol-generated 3D asteroid geometry, not real-world object scanning. Mining returns are not guaranteed.</div></section>
</main>`;}

function page(path){if(path==='/apps/metamask')return appsMetaMask();if(path==='/participate/mining')return miningReadmePage();
 if(Object.prototype.hasOwnProperty.call(pageRegistry,path)) return pageRegistry[path]();
 return '<main id="main-content" class="container section"><h1>Page not found</h1><p>The requested page does not exist.</p><a href="/" data-link>Back to home</a></main>';
}
function render(){disposeWhyAsteroid();miningUnmount();document.documentElement.lang=siteLanguage;disposeAsteroid();disposeAsteroid=()=>{};document.documentElement.dataset.theme=theme;document.documentElement.dir='ltr';let path;try{path=decodeURI(location.pathname).replace(/\/$/,'')||'/'}catch{path='/'}document.title=`${pages[path]?.title|| (path==='/whitepaper'?'Whitepaper':'Numen Network')} | Numen Network`;const description=pages[path]?.lead||'Numen Network: Proof of Scan Layer 1, GRANDPA finality and EVM compatibility.';document.querySelector('meta[name=description]')?.setAttribute('content',description);document.querySelector('link[rel=canonical]')?.setAttribute('href',network.website+path);document.querySelector('meta[property="og:title"]')?.setAttribute('content',document.title);document.querySelector('meta[property="og:description"]')?.setAttribute('content',description);app.innerHTML=header()+(path==='/'?home():page(path))+footer();if(path!=='/'){document.querySelector('main#main-content')?.classList.add('numen-inner-page');}disposeAsteroid=mountAsteroid(document.querySelector('#poscan-visual'));disposeWhyAsteroid=mountWhyAsteroid();if(path==='/mining/dashboard')miningMount();document.querySelectorAll('[data-link]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||e.button!==0)return;e.preventDefault();history.pushState({},'',a.getAttribute('href'));menuOpen=false;filter='All';render();scrollTo({top:0,behavior:'instant'});}));document.querySelectorAll('[data-metamask-direct]').forEach(a=>a.addEventListener('click',async(e)=>{e.preventDefault();e.stopImmediatePropagation();const proceed=window.confirm('Connect MetaMask to Numen Mainnet?\\n\\nMetaMask will ask you to approve adding or switching to the Numen network.\\n\\nSecurity: Confirm Chain ID 32026 and RPC https://rpc.numen-network.org. Never share your recovery phrase, private key, or password. Approve only if you trust this website.\\n\\nPress OK to continue to MetaMask.');if(!proceed)return;const provider=window.ethereum?.providers?.find(p=>p.isMetaMask)||window.ethereum;if(!provider?.request){alert('MetaMask was not detected. Please install or enable MetaMask.');return;}try{await provider.request({method:'wallet_addEthereumChain',params:[{chainId:'0x7d1a',chainName:'Numen Mainnet',rpcUrls:['https://rpc.numen-network.org'],nativeCurrency:{name:'Numen',symbol:'NUMN',decimals:18},blockExplorerUrls:['https://explorer.numen-network.org']}]});await provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x7d1a'}]});}catch(error){if(error.code!==4001)alert('MetaMask: '+(error.message||'Unable to switch network.'));}}));document.querySelector('#numen-metamask-connect')?.addEventListener('click',async()=>{const status=document.querySelector('#numen-metamask-status');const say=t=>{if(status)status.textContent=t};const provider=window.ethereum?.providers?.find(p=>p.isMetaMask)||window.ethereum;if(!provider?.request){say('MetaMask was not detected. Install or enable the extension, then retry.');return;}try{say('Waiting for MetaMask approval…');await provider.request({method:'eth_requestAccounts'});const chainId='0x7d1a';try{await provider.request({method:'wallet_switchEthereumChain',params:[{chainId}]});}catch(err){if(err.code!==4902&&err.data?.originalError?.code!==4902)throw err;await provider.request({method:'wallet_addEthereumChain',params:[{chainId,chainName:'Numen Mainnet',nativeCurrency:{name:'Numen',symbol:'NUMN',decimals:18},rpcUrls:['https://rpc.numen-network.org'],blockExplorerUrls:['https://explorer.numen-network.org']}]});await provider.request({method:'wallet_switchEthereumChain',params:[{chainId}]});}say('MetaMask connected to Numen Mainnet.');}catch(err){say(err.code===4001?'Request rejected in MetaMask.':`Connection failed: ${err.message||'Please try again.'}`)}});document.querySelector('#theme-btn')?.addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';try{localStorage.setItem('numen-theme',theme)}catch{}render()});document.querySelector('#menu-btn')?.addEventListener('click',()=>{menuOpen=!menuOpen;render();if(menuOpen)document.querySelector('.mobile-menu summary')?.focus();else document.querySelector('#menu-btn')?.focus()});document.querySelectorAll('[data-numen-demo]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.numenDemo);const stages=[['01 · Create a wallet','A wallet gives you an address to receive and manage NUMN. This is only a demonstration.','DEMO WALLET','0.00 NUMN','0x7A3…D91B · example address','◇','A fictional wallet preview — no keys or real balance.'],['02 · Send a transfer','In a real wallet you review the recipient, amount and network fee before signing. No transfer occurs here.','SIMULATED TRANSFER','1.00 NUMN','From 0x7A3…D91B → 0x2C8…F14A','⇄','Preview only · Not signed · Not broadcast'],['03 · Inspect the explorer','An actual explorer shows blocks, transactions and their on-chain status. This example is fictional.','EXPLORER PREVIEW','BLOCK # EXAMPLE','Status: simulated · no transaction hash','▦','See real network data in the Numen Explorer.']];const v=stages[i];['title','copy','label','number','address','icon','status'].forEach((k,j)=>{const el=document.getElementById('numen-demo-'+k);if(el)el.textContent=v[j]});document.querySelectorAll('[data-numen-demo]').forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))})}));document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render()}));document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='Copied'}catch{b.textContent='Select text'}}));document.querySelectorAll('.nav-button').forEach(b=>b.addEventListener('click',()=>{const g=b.parentElement;const was=g.classList.contains('open');document.querySelectorAll('.nav-group').forEach(x=>{x.classList.remove('open');x.querySelector('.nav-button')?.setAttribute('aria-expanded','false')});if(!was)g.classList.add('open');b.setAttribute('aria-expanded',String(!was))}));}
// HEADER NAVIGATION: Close desktop dropdowns consistently.
function closeDesktopMenus() {
  document.querySelectorAll('.nav-group').forEach(group => {
    group.classList.remove('open');
    group.querySelector('.nav-button')?.setAttribute('aria-expanded', 'false');
  });
}

// Close dropdowns with Escape and return keyboard focus to their trigger.
document.addEventListener('keydown', (event) => {
  if (event.key !== 'Escape') return;
  const opened = document.querySelector('.nav-group.open');
  if (opened) {
    const trigger = opened.querySelector('.nav-button');
    closeDesktopMenus();
    trigger?.focus();
  }
});

// Close when focus moves outside the desktop navigation.
document.addEventListener('focusin', (event) => {
  if (!event.target.closest('.desktop-nav')) closeDesktopMenus();
});

// Close the mobile navigation with Escape; search shortcuts were removed.
window.addEventListener('popstate', render);
document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape' && menuOpen) {
    menuOpen = false;
    render();
    document.querySelector('#menu-btn')?.focus();
  }
});
document.addEventListener('click', (event) => {
  if (!event.target.closest('.nav-group')) {
    closeDesktopMenus();
  }
});
render();
